xwikidoc.content:
{{velocity}}
## The element, and the module from the attachment of AttachmentManager.Code (?rev: a new import is not cached).
## ?page=Space.Page in the URL shows the attachments of another page, else those of this page. ($! : without the
## parameter, escapetool returns null, and Velocity would print the expression itself.)
#set ($codeDoc = $xwiki.getDocument('AttachmentManager.Code'))
#set ($module = $codeDoc.getAttachment('xwiki-attachment-manager.js'))
{{html clean="false"}}
<xwiki-attachment-manager page="$!escapetool.xml($!request.page)"></xwiki-attachment-manager>
<script type="module" src="$codeDoc.getAttachmentURL('xwiki-attachment-manager.js')?rev=$!module.version"></script>
{{/html}}
{{/velocity}}
